import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertService } from 'src/app/services/alert.service';
import { IonicStorageService } from 'src/app/services/ionic-storage/ionic-storage.service';

@Component({
  selector: 'app-cwsn-menu',
  templateUrl: './cwsn-menu.page.html',
  styleUrls: ['./cwsn-menu.page.scss'],
})
export class CwsnMenuPage implements OnInit {
  mode : any;
  splEducatorBlockId: any;
  dataInLolDB: boolean = false;
  clustoers: any = [];
  zonalId:any = '';
  routeData: any;
  title: any;
  usertype: any;

  phase2MenuList: Array<{ 'label': any, 'value': any, 'img': any }> = [
    { label: 'Functional Assessment', value: '1',img: '../../../../assets/icons/cwsn/Functional-Grey.svg' },
    { label: 'Annual Evalution', value: '2',img: '../../../../assets/icons/cwsn/Annual Evaluation-Grey.svg' },
    { label: 'Goal Setting for Next Academic Year', value: '3',img: '../../../../assets/icons/cwsn/Goal-Grey.svg' }
  ];
  // allStudentData: any;
  SchoolId: number;


  constructor(
    private router: Router,
    private ionicstorage: IonicStorageService,
    private route:ActivatedRoute,
    private alertService:AlertService
  ) { 

   }


  ngOnInit() {

  }

  ionViewDidEnter() {
    this.routeData = this.route.snapshot; 
    this.title = this.routeData.queryParams.title;   
    this.mode = this.routeData.queryParams.mode;
    console.log('title',this.title,'mode',this.mode);

    // item: JSON.stringify(item)
    // this.route.queryParams.subscribe(data => {
    //   this.allStudentData = JSON.parse(data.item);
    //   console.log('queryParams allStudentData', this.allStudentData);
    // })

    this.ionicstorage.getData('getUserDetailsCwsn').then (
      (userData) => {
        console.log('userData',userData)
        this.usertype = userData;
        console.log('usertype',this.usertype)
      })
    // this.checkLocalDB();
  }

  navigateTo(val) {
   if(val==1) {
    this.router.navigate(['/tabs/cwsn/ca-school-list'], { queryParams: { 'mode': this.mode, 'title': this.title} })
   }else {
    this.alertService.warning("Will be enable soon");
   }
    // this.router.navigate(['/tabs/cwsn/ca-cluster'],{ queryParams: { title: this.title,mode: this.mode } })
  }

  navigateBack() {
    // this.router.navigate(['/tabs/cwsn-menu'], { queryParams: { 'mode': this.mode, 'title': this.title} })

    this.router.navigate(['/tabs/cwsn/dashboard'])
  }


}
